<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { api } from '@/services/api'
import { useToastStore } from '@/stores/toast'
import AdminPageHeader from '@/components/common/AdminPageHeader.vue'
import UiIcon from '@/components/common/UiIcon.vue'
const toast=useToastStore();const loading=ref(true);const saving=ref(false);const testing=ref(false);const error=ref('');const recipient=ref('')
const form=reactive<Record<string,any>>({enabled:false,host:'',port:587,username:'',password:'',fromEmail:'',fromName:'TrastCMS',auth:true,startTls:true,ssl:false,replyTo:'',passwordConfigured:false})
onMounted(load)
async function load(){loading.value=true;try{Object.assign(form,await api('/api/admin/mail/settings'));recipient.value=form.fromEmail||''}finally{loading.value=false}}
async function save(){saving.value=true;error.value='';try{const saved=await api<Record<string,any>>('/api/admin/mail/settings',{method:'PUT',body:JSON.stringify(form)});Object.assign(form,saved,{password:''});toast.success('Configuración SMTP guardada.')}catch(e){error.value=e instanceof Error?e.message:'No se pudo guardar'}finally{saving.value=false}}
async function test(){testing.value=true;error.value='';try{const result=await api<Record<string,any>>('/api/admin/mail/test',{method:'POST',body:JSON.stringify({recipient:recipient.value})});if(!result.delivered)throw new Error(result.message||'No se pudo entregar el correo');toast.success(result.message||'Correo de prueba enviado.')}catch(e){error.value=e instanceof Error?e.message:'No se pudo enviar el correo de prueba'}finally{testing.value=false}}
</script>
<template><section class="space-y-6"><AdminPageHeader eyebrow="SERVICIO COMPARTIDO" title="Correo electrónico" description="SMTP central para que TrastTravel y los demás plugins envíen notificaciones sin duplicar credenciales ni lógica."><template #actions><button class="button secondary" type="button" :disabled="testing||!recipient" @click="test"><UiIcon name="send" :size="16"/>{{ testing?'Enviando…':'Enviar prueba' }}</button><button class="button" type="button" :disabled="saving" @click="save"><UiIcon name="check" :size="16"/>Guardar</button></template></AdminPageHeader><p v-if="error" class="form-error">{{ error }}</p><div v-if="loading" class="panel empty">Cargando configuración…</div><template v-else><div class="grid gap-6 xl:grid-cols-[1fr_.72fr]"><form class="panel space-y-6" @submit.prevent="save"><div class="flex items-center justify-between rounded-2xl bg-slate-50 p-4"><div><h2 class="font-bold">Habilitar correo saliente</h2><p class="text-sm text-slate-500">Los plugins usarán PlatformMailService.</p></div><label class="switch-control"><input v-model="form.enabled" type="checkbox"><span></span></label></div><div class="grid gap-4 md:grid-cols-2"><label>Servidor SMTP<input v-model="form.host" placeholder="smtp.gmail.com"></label><label>Puerto<input v-model.number="form.port" type="number" min="1" max="65535"></label><label>Usuario<input v-model="form.username" autocomplete="username"></label><label>Contraseña de aplicación<input v-model="form.password" type="password" autocomplete="new-password" :placeholder="form.passwordConfigured?'Ya configurada; deje vacío para conservarla':'Ingrese la contraseña'"><small v-if="form.passwordConfigured">Hay una contraseña cifrada almacenada.</small></label><label>Correo remitente<input v-model="form.fromEmail" type="email"></label><label>Nombre remitente<input v-model="form.fromName"></label><label>Responder a<input v-model="form.replyTo" type="email"></label></div><div class="grid gap-3 md:grid-cols-3"><label class="option-check"><input v-model="form.auth" type="checkbox"><span><b>Autenticación</b><small>Usuario y contraseña.</small></span></label><label class="option-check"><input v-model="form.startTls" type="checkbox"><span><b>STARTTLS</b><small>Recomendado en puerto 587.</small></span></label><label class="option-check"><input v-model="form.ssl" type="checkbox"><span><b>SSL directo</b><small>Común en puerto 465.</small></span></label></div><div class="flex justify-end"><button class="button" :disabled="saving">{{ saving?'Guardando…':'Guardar SMTP' }}</button></div></form><aside class="space-y-6"><section class="panel"><span class="eyebrow">PRUEBA DE ENTREGA</span><h2 class="mt-1 text-xl font-bold">Verificar configuración</h2><p class="mt-2 text-sm leading-6 text-slate-500">Guarde primero los cambios y envíe un mensaje real para comprobar conexión, autenticación y remitente.</p><label class="mt-5 block">Destinatario<input v-model="recipient" class="mt-2" type="email" placeholder="correo@ejemplo.com"></label><button class="button mt-4 w-full" :disabled="testing||!recipient" @click="test">{{ testing?'Enviando…':'Enviar correo de prueba' }}</button></section><section class="rounded-2xl border border-sky-200 bg-sky-50 p-5 text-sm text-sky-950"><b>Uso por plugins</b><p class="mt-2 leading-6">TrastTravel envía confirmaciones de reservación y pago. Otros plugins pueden inyectar <code>PlatformMailService</code> y reutilizar exactamente esta configuración.</p></section><section class="rounded-2xl border border-amber-200 bg-amber-50 p-5 text-sm text-amber-950"><b>Seguridad</b><p class="mt-2 leading-6">La contraseña SMTP se almacena cifrada con la clave maestra de plugins y nunca vuelve al navegador.</p></section></aside></div></template></section></template>
<style scoped>.switch-control{position:relative;width:50px;height:28px}.switch-control input{opacity:0}.switch-control span{position:absolute;inset:0;border-radius:999px;background:#cbd5e1;transition:.2s}.switch-control span:after{content:'';position:absolute;width:22px;height:22px;left:3px;top:3px;border-radius:50%;background:white;transition:.2s}.switch-control input:checked+span{background:#7c3aed}.switch-control input:checked+span:after{transform:translateX(22px)}</style>
